// Match the opening lesson cards to the textbook's actual teaching sequence.
(() => {
  const u1 = MATH_1_DATA[0];
  u1.description = 'Count and write whole numbers from 0 to 100; use tens and ones, compare/order numbers, recognise ordinals, and match one-to-one groups.';
  u1.sections = [
    makeMath1Section('1.1', 'Counting 0–9 and Zero', 'Count pictured objects one by one and match each group with its numeral. Zero names an empty group; the book introduces it with empty examples such as no legs or no apples.', ['Point to each object exactly once while counting.', 'Zero means none; it is a number, not a blank.'], [{ problem: 'A plate has no apples. How many apples are there?', steps: ['There are no apples to count.'], answer: '0 apples' }]),
    makeMath1Section('1.2', 'Counting and Writing Numbers to 100', 'Count forward and backward, recognise the numbers 10–100, and read/write the number sequence. Ten ones make one ten; two-digit numbers show tens and leftover ones.', ['After 9 comes 10; after 99 comes 100.', 'Build tens by grouping ten ones together.'], [{ problem: 'Show 28 using tens and ones.', steps: ['Group 20 as two tens.', 'The remaining 8 are ones.'], answer: '2 tens and 8 ones' }]),
    makeMath1Section('1.3', 'Place Value: Tens and Ones', 'A two-digit number is made of tens and ones. For example, 57 means five tens and seven ones: 50 + 7.', ['The left digit counts tens; the right digit counts ones.', 'A zero in the ones place means no extra ones.'], [{ problem: 'Write 70 as tens and ones.', steps: ['The tens digit 7 means seven tens.', 'The ones digit 0 means zero ones.'], answer: '7 tens and 0 ones' }]),
    makeMath1Section('1.4', 'Before, After and Between', 'Find the number immediately before or after a given number, or the number between two neighbours. The number line and counting sequence show the order.', ['Before is one less; after is one more.', 'Between consecutive gaps there is one whole number.'], [{ problem: 'What number comes between 39 and 41?', steps: ['Count 39, 40, 41.'], answer: '40' }]),
    makeMath1Section('1.5', 'Compare, Order and Ordinal Position', 'Compare two whole numbers with greater than or less than language, arrange sets in ascending or descending order, and describe positions using ordinal numbers. One-to-one matching compares groups by pairing objects.', ['Compare tens before ones in two-digit numbers.', 'Ascending goes smallest to greatest; descending goes greatest to smallest.', 'Ordinal positions on picture pages follow the indicated direction.'], [{ problem: 'Arrange 18, 16, 17 in ascending order.', steps: ['The smallest is 16, then 17, then 18.'], answer: '16, 17, 18' }])
  ];
  u1.workedExamples = [
    { id: 'ex1', title: 'Source example: make a ten (p. 15)', problem: 'How many ones make one ten?', given: 'Ten individual objects', method: 'Group ten ones together.', steps: ['Count 1 through 10.', 'Ten ones are exchanged for one group of ten.'], answer: '10 ones = 1 ten', sourcePages: [15] },
    { id: 'ex2', title: 'Source example: represent 14 (p. 17)', problem: 'Show 14 using tens and ones.', given: '14 objects', method: 'Make one group of ten, then count leftovers.', steps: ['Set aside 10 objects as one ten.', '4 objects remain as ones.'], answer: '1 ten and 4 ones', sourcePages: [17] }
  ];
  const u2 = MATH_1_DATA[1];
  u2.description = 'Add groups and prices, find how much more or less, subtract objects, solve missing-number equations and mental arithmetic through two-digit numbers.';
  u2.sections = [
    makeMath1Section('2.1', 'How Much More? Compare Two Amounts', 'To find how much more one group or number has than another, subtract the smaller amount from the larger.', ['Difference = larger amount − smaller amount.', 'Use the named units in the answer.'], [{ problem: 'How much more is 14 than 9?', steps: ['14 − 9 = 5.'], answer: '5 more' }]),
    makeMath1Section('2.2', 'Addition: Join and Count On', 'Addition combines groups. Count on from one group to find the total; the plus sign (+) joins the addends and the equals sign (=) states their total.', ['Count each object once.', 'Use objects, fingers or a number line to check the sum.'], [{ problem: 'Add 5 + 3.', steps: ['Start at 5 and count on 3: 6, 7, 8.'], answer: '8' }]),
    makeMath1Section('2.3', 'Add One-Digit and Two-Digit Numbers', 'The book progresses from picture sums to teen numbers and two-digit addition. Add ones to ones and tens to tens; use mental counting or place-value columns.', ['Adding zero leaves a number unchanged.', 'Align tens and ones when writing a vertical sum.'], [{ problem: 'Add 37 + 42.', steps: ['Tens: 30 + 40 = 70.', 'Ones: 7 + 2 = 9.', '70 + 9 = 79.'], answer: '79', sourcePages: [53] }]),
    makeMath1Section('2.4', 'Subtraction: Take Away and Find What Remains', 'Subtraction removes objects or finds a difference. Cross out or take away the stated number, then count what remains.', ['Start with the whole amount.', 'Check by adding the remainder and removed amount.'], [{ problem: 'There are 8 objects; take away 5.', steps: ['8 − 5 = 3.'], answer: '3 remain' }]),
    makeMath1Section('2.5', 'How Much Less? Missing Numbers', 'Find how much less by subtracting. In a missing-number sentence, use counting on or the inverse operation to find the empty value.', ['If a − □ = c, then □ = a − c.', 'If □ − b = c, then □ = c + b.'], [{ problem: 'Find □: 14 − □ = 10.', steps: ['14 − 10 = 4.'], answer: '□ = 4' }]),
    makeMath1Section('2.6', 'Mental Addition and Subtraction', 'Break teen numbers into a ten and ones, then add or subtract the small parts mentally. The book practises quick sums and differences with numbers through 19.', ['Keep the ten separate while combining the ones.', 'Use subtraction to check an addition.'], [{ problem: 'Calculate 13 − 2 mentally.', steps: ['13 = 10 + 3.', '10 + (3 − 2) = 11.'], answer: '11' }])
  ];
  u1.sections.forEach((section, i) => { if (MATH_1_URDU[1][i]) Object.assign(section, { theoryUrdu: MATH_1_URDU[1][i].theory, rulesUrdu: MATH_1_URDU[1][i].rules }); });
  u2.sections.forEach((section, i) => { if (MATH_1_URDU[2][i]) Object.assign(section, { theoryUrdu: MATH_1_URDU[2][i].theory, rulesUrdu: MATH_1_URDU[2][i].rules }); });
})();

